item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish variation across runs."
        }
      ],
      "instrument_review": "MESA 14: repeated testing is Not sure. MESA 16: no across-run uncertainty findings establish stability; missing evidence is not evidence of instability."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "An unreplicated result establishes neither stability nor instability."
        }
      ],
      "instrument_review": "MESA 14: No, because non-repetition is explicit. MESA 16: the single run cannot establish score variation across runs."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated testing under the same conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. MESA 16 and 25: the reported range supports stability under the stated definition for this comparison."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Testing occurred regardless of whether the results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14: Yes, repeated testing occurred. MESA 16 and 25: the findings explicitly conflict with stability under the supplied definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The documentation adds no evidence about score stability."
        }
      ],
      "instrument_review": "MESA 22: installation guidance helps describe setup. It does not resolve MESA 14 or 16 concerning repeated testing and score variation."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A performed better on the evaluated puzzles under the described scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These findings do not establish a general-intelligence ranking across domains."
        }
      ],
      "instrument_review": "MESA 2 and 25: the narrow comparison fits the stated intended use. MESA 9 and 20: cross-domain coverage and evidence for broader performance are not supplied."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed results support A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of greater general intelligence."
        }
      ],
      "instrument_review": "MESA 2: the intended use is described. MESA 9, 20 and 25: the available coverage and findings do not justify selecting for general intelligence across domains."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checks and a difference interval of 12 to 28 percentage points support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness results alone do not establish an improvement in workplace safety."
        }
      ],
      "instrument_review": "MESA 20: the later trial supplies relevant real-work evidence absent initially. MESA 16: the difference interval supports the correctness comparison. MESA 25: conclusions should remain limited to correctness in the studied workshop and conditions."
    }
  ],
  "closing_note": "No clarification was needed. Probe labels classify statements; MESA distinguishes whether testing occurred from whether results were favourable, and missing evidence from explicit contradiction."
}
